const trigger = $('Normalize Input').first().json;
const stamp = Date.now();
const escalationId = 'ESC-' + stamp;
const department = (trigger.department || '').trim() || 'Front Desk';
const urgency = (trigger.urgency || '').trim().toLowerCase() === 'high' ? 'high' : 'normal';
const guestName = trigger.guest_name;
const contact = trigger.contact;
const requestDetails = trigger.request_details;

const urgencyColor = urgency === 'high' ? '#D64545' : '#3B6BC4';
const urgencyLabel = urgency === 'high' ? 'HIGH URGENCY' : 'NORMAL';
const escapeHtml = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const emailHtml = `
<div style="font-family: -apple-system, Arial, sans-serif; max-width: 600px; margin: 0 auto; border: 1px solid #e5e5e5; border-radius: 10px; overflow: hidden;">
  <div style="background: #1A2B4C; color: #ffffff; padding: 18px 24px;">
    <span style="font-size: 13px; letter-spacing: 0.5px; opacity: 0.8;">GRANDVIEW HOTEL</span>
    <h2 style="margin: 4px 0 0; font-size: 18px; font-weight: 600;">Guest Needs Staff Follow-Up</h2>
  </div>
  <div style="padding: 22px 24px 8px;">
    <span style="display: inline-block; padding: 4px 12px; border-radius: 999px; font-size: 11px; font-weight: 700; letter-spacing: 0.5px; color: #ffffff; background: ${urgencyColor};">${urgencyLabel}</span>
    <span style="display: inline-block; margin-left: 8px; padding: 4px 12px; border-radius: 999px; font-size: 11px; font-weight: 600; color: #444444; background: #F0F1F4;">${escapeHtml(department).toUpperCase()}</span>
    <table style="width: 100%; margin-top: 18px; border-collapse: collapse; font-size: 14px;">
      <tr>
        <td style="padding: 7px 0; color: #888888; width: 110px; vertical-align: top;">Guest</td>
        <td style="padding: 7px 0; font-weight: 600; color: #1A2B4C;">${escapeHtml(guestName)}</td>
      </tr>
      <tr>
        <td style="padding: 7px 0; color: #888888; vertical-align: top;">Contact</td>
        <td style="padding: 7px 0; color: #222222;">${escapeHtml(contact)}</td>
      </tr>
      <tr>
        <td style="padding: 7px 0; color: #888888; vertical-align: top;">Escalation ID</td>
        <td style="padding: 7px 0; color: #222222; font-family: monospace; font-size: 13px;">${escapeHtml(escalationId)}</td>
      </tr>
    </table>
    <div style="margin-top: 18px; padding: 14px 16px; background: #F7F7F9; border-left: 3px solid #1A2B4C; border-radius: 6px;">
      <div style="font-size: 11px; color: #999999; text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 6px;">Guest Request</div>
      <div style="font-size: 14px; color: #222222; white-space: pre-wrap; line-height: 1.5;">${escapeHtml(requestDetails)}</div>
    </div>
  </div>
  <div style="padding: 14px 24px; margin-top: 10px; background: #FAFAFA; border-top: 1px solid #EFEFEF; font-size: 12px; color: #999999;">
    Logged automatically by Aria, the AI receptionist &middot; ${new Date().toUTCString()}
  </div>
</div>`;

return [{
  json: {
    escalation_id: escalationId,
    guest_name: guestName,
    contact: contact,
    request_details: requestDetails,
    department,
    urgency,
    email_html: emailHtml
  }
}];

const raw = $input.item.json;
const SHARED_SECRET = 'YOUR_SHARED_SECRET';

let body;
if (raw.headers && raw.body !== undefined) {
  const providedKey = raw.headers['x-api-key'] || raw.headers['X-Api-Key'];
  if (providedKey !== SHARED_SECRET) {
    throw new Error('Unauthorized: missing or invalid x-api-key header');
  }
  body = raw.body;
} else {
  body = raw;
}

return [{
  json: {
    guest_name: body.guest_name,
    contact: body.contact,
    request_details: body.request_details,
    department: body.department,
    urgency: body.urgency
  }
}];
